'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey=(d=new Date())=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(d);
const DEADLINE='2026-11-13', STORAGE='mathegarten-v1';
let TODAY=dayKey(),daysLeft=Math.round((Date.parse(DEADLINE)-Date.parse(TODAY))/86400000);
function refreshDay(){TODAY=dayKey();daysLeft=Math.round((Date.parse(DEADLINE)-Date.parse(TODAY))/86400000);}
const fresh=()=>({version:1,points:0,records:{},days:{},settings:{sfx:true,volume:35,reduce:false},session:null});
let store=fresh(), storageOK=true;
try{const raw=localStorage.getItem(STORAGE);if(raw)store=validateStore(JSON.parse(raw));}catch{storageOK=false;}
let view='home', session=null, qState=null, selectedTopic=null, mode='practice', audioOn=false;
const app=$('#app');
let cloudApplying=false;
function validateStore(data){
 if(!data||data.version!==1||!data.records||!data.days)throw Error('Das ist keine Mathegarten-Sicherung.');
 const out=fresh(),num=(v,max=1e7)=>Number.isFinite(v)?Math.min(max,Math.max(0,Math.floor(v))):0;
 out.points=num(data.points);
 for(const q of QUESTIONS){const r=data.records[q.id];if(r&&typeof r==='object')out.records[q.id]={tries:num(r.tries),clean:num(r.clean),missed:r.missed===true,last:typeof r.last==='string'?r.last.slice(0,10):'',streak:num(r.streak,1000)};}
 for(const [d,v] of Object.entries(data.days).slice(-1000)){if(/^\d{4}-\d{2}-\d{2}$/.test(d)&&v&&typeof v==='object')out.days[d]={solved:num(v.solved),correct:num(v.correct)};}
 out.settings={sfx:data.settings?.sfx!==false,volume:num(data.settings?.volume??35,100),reduce:data.settings?.reduce===true};
 const s=data.session;
 if(s&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.length<=200&&s.ids.every(id=>QUESTIONS.some(q=>q.id===id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<=s.ids.length&&Array.isArray(s.results)&&s.results.length===s.index&&s.results.every((r,i)=>r&&r.id===s.ids[i])){out.session={ids:s.ids,index:s.index,results:s.results.map(r=>({id:String(r.id),correct:r.correct===true,assisted:r.assisted===true})),mode:['practice','daily','original','exam','review'].includes(s.mode)?s.mode:'practice',title:typeof s.title==='string'?s.title.slice(0,80):'Deine Runde'};if(s.draft&&s.draft.id===s.ids[s.index])out.session.draft=cleanDraft(s.draft);}
 return out;
}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(store));storageOK=true;if(!cloudApplying)window.GardenCloud?.changed();}catch{storageOK=false;}}
function cleanDraft(d){const q=QUESTIONS.find(q=>q.id===d.id);if(!q)return null;const a=d.answer;let answer;switch(q.kind){case'input':answer=q.fields.map((_,i)=>typeof a?.[i]==='string'?a[i].slice(0,40):'');break;case'bits':answer=Number.isInteger(a)&&a>=0&&a<2**q.width?a:0;break;case'formula':answer=typeof a==='string'&&/^[ABC¬∧∨⊕()]*$/.test(a)?a.slice(0,100):'';break;case'equiv':answer={equal:typeof a?.equal==='boolean'?a.equal:null,reason:Number.isInteger(a?.reason)&&a.reason>=0&&a.reason<q.reasons.length?a.reason:null};break;case'table':answer=q.rows.map((_,i)=>q.cols.map((_,j)=>typeof a?.[i]?.[j]==='boolean'?a[i][j]:null));break;case'match':answer={};for(let i=0;i<q.pairs.length;i++)if(Number.isInteger(a?.[i])&&a[i]>=0&&a[i]<q.pairs.length)answer[i]=a[i];break;default:answer=Number.isInteger(a)&&a>=0&&a<(q.options||q.names).length?a:null;}return {id:q.id,answer,attempts:Number.isInteger(d.attempts)?Math.max(0,Math.min(1000,d.attempts)):0,hinted:d.hinted===true};}
function persistRound(){if(view!=='game'||!session||!qState)return;const checkpoint=JSON.parse(JSON.stringify(session));delete checkpoint.draft;if(qState.done){checkpoint.index++;store.session=checkpoint.index>=checkpoint.ids.length&&mode!=='exam'?null:checkpoint;}else{checkpoint.draft={id:current().id,answer:qState.answer,attempts:qState.attempts,hinted:qState.hinted};store.session=checkpoint;}save();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function icon(name,cls=''){
 const paths={sprout:'<path d="M32 51V29M32 36C11 38 9 18 10 15c14-1 25 5 22 21ZM32 29C31 14 43 8 54 10c0 13-7 21-22 19Z"/>',palette:'<path d="M52 37C61 18 43 7 29 11 5 16 8 48 25 53c9 3 8-9 15-9 9 1 9-2 12-7Z"/><circle cx="24" cy="24" r="3"/><circle cx="37" cy="20" r="3"/><circle cx="45" cy="30" r="3"/><circle cx="20" cy="37" r="3"/>',pond:'<ellipse cx="32" cy="44" rx="24" ry="11"/><path d="M16 43c8 5 24 5 32 0M32 38V19M32 30c-15 1-18-9-16-12 11-2 16 4 16 12ZM32 25c-1-12 10-15 16-14 1 10-5 15-16 14Z"/>',mail:'<rect x="10" y="24" width="44" height="29" rx="7"/><path d="m12 27 20 14 20-14M22 24V11h20v13M27 17h10"/>',blocks:'<rect x="9" y="32" width="23" height="23" rx="5"/><rect x="34" y="32" width="23" height="23" rx="5"/><rect x="22" y="7" width="23" height="23" rx="5"/><path d="M29 18h9M20 39v9m-4-4h8m17-5 8 9m0-9-8 9"/>',flask:'<path d="M24 8h16M27 8v18L14 47c-3 6 0 9 6 9h24c6 0 9-3 6-9L37 26V8M22 37h20"/><circle cx="30" cy="44" r="2"/><circle cx="39" cy="49" r="2"/>',home:'<path d="m10 29 22-19 22 19M16 25v29h32V25M27 54V36h10v18"/>',star:'<path d="m32 8 7 16 18 2-13 12 4 18-16-9-16 9 4-18L7 26l18-2Z"/>',book:'<path d="M32 16C22 9 9 13 9 13v39s13-4 23 3c10-7 23-3 23-3V13s-13-4-23 3Zm0 0v39"/>',music:'<path d="M24 46V16l28-6v30M24 24l28-6"/><ellipse cx="16" cy="48" rx="8" ry="6"/><ellipse cx="44" cy="42" rx="8" ry="6"/>',settings:'<circle cx="32" cy="32" r="10"/><path d="m27 9 10 0 2 8 7 4 8-2 5 9-6 6v8l-7 8-8-2-7 4-7-4-8 2-6-10 4-7-2-8 7-5 6-1Z"/>',arrow:'<path d="M12 32h40M37 17l15 15-15 15"/>',back:'<path d="M52 32H12m15-15L12 32l15 15"/>',check:'<path d="m13 32 13 13 26-28"/>',repeat:'<path d="M50 24A20 20 0 1 0 52 40M50 10v14H36"/>',leaf:'<path d="M14 50C2 24 29 8 53 11c0 31-16 47-39 39Zm0 0 29-29"/>',clock:'<circle cx="32" cy="32" r="23"/><path d="M32 17v16l11 6"/>',close:'<path d="m18 18 28 28m0-28L18 46"/>',sun:'<circle cx="32" cy="32" r="12"/><path d="M32 3v7m0 44v7M3 32h7m44 0h7M11 11l6 6m30 30 6 6M11 53l6-6m30-30 6-6"/>',heart:'<path d="M32 54 11 32C-3 15 19 2 32 19 45 2 67 15 53 32Z"/>'};
 return `<svg class="icon ${cls}" viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.leaf}</svg>`;
}
function mascot(size='hero'){
 return `<svg class="mascot ${size}" viewBox="0 0 400 300" aria-hidden="true"><defs><linearGradient id="pot${size}" x2=".8" y2="1"><stop stop-color="#f3bd9e"/><stop offset="1" stop-color="#e6a58c"/></linearGradient></defs><ellipse cx="210" cy="265" rx="111" ry="13" fill="#d7dfce" opacity=".5"/><g class="float-cloud"><path d="M54 82c-13 0-15-20 0-22 0-22 35-26 43-9 21-6 30 30 8 31Z" fill="#fffdf6"/><path d="M291 67c-10-5-2-21 9-19 9-21 33-12 35 1 19 0 22 24 2 23Z" fill="#fffdf6"/></g><g class="sprout-sway"><path d="M203 189c-5-47 5-77 1-107" stroke="#698a65" stroke-width="9" fill="none" stroke-linecap="round"/><path d="M202 128c-56 9-85-25-79-56 48-4 82 10 79 56" fill="#91b78a"/><path d="M205 103c-2-48 40-65 77-56-1 40-32 65-77 56" fill="#739b70"/><path d="m147 91 54 35m7-24 52-37" fill="none" stroke="#577b56" stroke-width="3" opacity=".5"/></g><path d="m145 180 15 64c6 26 88 25 95 0l16-64Z" fill="url(#pot${size})"/><rect x="135" y="169" width="146" height="27" rx="12" fill="#efb69b"/><ellipse cx="184" cy="219" rx="4" ry="6" fill="#5a6150"/><ellipse cx="231" cy="219" rx="4" ry="6" fill="#5a6150"/><path d="M199 226q9 11 17 0" fill="none" stroke="#5a6150" stroke-width="3" stroke-linecap="round"/><ellipse cx="172" cy="229" rx="8" ry="4" fill="#df8f85" opacity=".5"/><ellipse cx="243" cy="229" rx="8" ry="4" fill="#df8f85" opacity=".5"/><g fill="#f2d887"><path d="m90 163 4-11 4 11 11 4-11 4-4 11-4-11-11-4Z"/><path d="m305 132 3-9 3 9 9 3-9 3-3 9-3-9-9-3Z"/></g><g fill="#778968" font-family="Segoe UI, sans-serif" font-weight="700" font-size="22"><text x="72" y="127" transform="rotate(-12 72 127)">01</text><text x="302" y="199" transform="rotate(13 302 199)">∧</text><text x="116" y="42" font-size="20">+</text></g><path d="M83 248c-4-20 7-25 13-22-1 12-9 19-13 22m1-1c-15-10-23-4-22 2 11 4 17 2 22-2" fill="#91b78a"/></svg>`;
}
function sidebar(){return `<aside class="sidebar"><button class="brand" data-action="home">${icon('sprout')}<span>mathe<span class="brand-end">garten</span><small>kleine spiele. großes wachsen.</small></span></button><nav aria-label="Hauptnavigation"><button data-action="home" class="nav-button ${view==='home'?'active':''}">${icon('home')} Mein Garten</button><button data-action="daily" class="nav-button">${icon('sun')} Meine Tagesrunde <span class="tiny-dot"></span></button><button data-action="review" class="nav-button">${icon('repeat')} Nochmal wachsen <span class="nav-count">${Object.values(store.records).filter(r=>r.missed).length}</span></button><button data-action="guide" class="nav-button">${icon('book')} Kleines Lernbuch</button></nav><div class="nav-label">DEINE THEMENINSELN</div><nav class="topic-nav" aria-label="Themeninseln">${TOPICS.map(t=>`<button data-action="topic" data-id="${t.id}" class="nav-button ${selectedTopic===t.id&&view==='topic'?'active':''}"><span class="topic-dot ${t.color}"></span>${t.label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="quiet-note">${icon('leaf')} In deinem Tempo.<br>Ein Schritt zählt auch.</div><button data-action="settings" class="nav-button">${icon('settings')} Einstellungen & Sicherung</button></div></aside>`;}
function shell(content){
 document.body.classList.toggle('reduced',store.settings.reduce);
 app.innerHTML=`${sidebar()}<div class="page"><header class="topbar"><button class="mobile-brand" data-action="home">${icon('sprout')} mathegarten</button><span class="breadcrumb">DEIN KLEINER ORT ZUM VERSTEHEN</span><div class="top-actions"><button id="music-toggle" class="pill music-button ${audioOn?'playing':''}" data-action="music" aria-pressed="${audioOn}">${icon('music')} <span>Musik ${audioOn?'an':'aus'}</span><i class="sound-bars"><b></b><b></b><b></b></i></button><span class="points" title="Gesammelte Blüten">${icon('star')} <b>${store.points}</b><span> Blüten</span></span></div></header><main id="main" tabindex="-1">${content}</main><footer class="footer"><span>${icon('heart')} Mit Ruhe lernen. Mit Freude wachsen.</span><button data-action="sources">Über dein Übungsblatt</button><button class="cloud-pill" data-cloud-action="open" title="Spielstand auf PC und Handy"><span class="cloud-dot"></span><span data-cloud-status>Auf diesem Gerät</span></button></footer></div><nav class="mobile-nav" aria-label="Mobile Navigation"><button data-action="home" aria-label="Garten">${icon('home')}Garten</button><button data-action="daily" aria-label="Tagesrunde">${icon('sun')}Tagesrunde</button><button data-action="review" aria-label="Wiederholen">${icon('repeat')}Wiederholen</button><button data-action="settings" aria-label="Einstellungen">${icon('settings')}Mehr</button></nav><dialog id="modal"></dialog>`;
 window.scrollTo({top:0,behavior:'instant'});window.GardenCloud?.paint();
 if(!storageOK)toast('Dein Browser erlaubt gerade keine Speicherung. Sichere deinen Stand über Einstellungen.');
}
function topicProgress(t){const qs=QUESTIONS.filter(q=>q.topic===t.id&&q.original),n=qs.filter(q=>store.records[q.id]?.clean>0).length;return {n,total:qs.length,pct:Math.round(n/qs.length*100)};}
function home(){refreshDay();view='home';selectedTopic=null;const d=store.days[TODAY]||{solved:0,correct:0};
 shell(`<section class="welcome"><div><div class="eyebrow"><span class="mini-flower">✿</span> HEY MERT, SCHÖN, DASS DU DA BIST.</div><h1>Ein bisschen spielen.<br><span>Ein bisschen wachsen.</span></h1><p>Mach es dir gemütlich. Dein Mathe-Abenteuer<br class="desktop-break"> beginnt mit einem kleinen Schritt.</p><div class="hero-actions"><button class="btn primary" data-action="daily">Meine Tagesrunde ${icon('arrow')}</button><span>8 kleine Aufgaben<br><b>ganz in deinem Tempo</b></span></div><div class="hero-date">${icon('clock')} ${daysLeft>0?`Noch ${daysLeft} ${daysLeft===1?'Tag':'Tage'} bis Freitag, 13. November`:daysLeft===0?'Heute ist dein Klausurtag. Zeit für ein ruhiges Warm-up.':'Dein Garten bleibt zum Weiterüben offen.'}</div></div><div class="hero-art">${mascot()}<span class="speech">Du musst noch nicht<br>alles können.</span><span class="art-caption">Jede Runde lässt dich wachsen.</span></div></section>
 ${store.session?`<div class="resume-strip"><span>${icon('leaf')} Deine angefangene Runde wartet: <b>${esc(store.session.title)}</b></span><button class="btn small" data-action="resume">${store.session.index===store.session.ids.length?'Auswertung ansehen':`Weiter bei ${store.session.index+1} / ${store.session.ids.length}`} ${icon('arrow')}</button></div>`:''}
 <section class="section-heading"><div><div class="eyebrow">DEINE THEMENINSELN</div><h2>Worauf hast du heute Lust?</h2></div><span class="muted">Alles ist offen. Such dir etwas aus.</span></section><section class="topic-grid">${TOPICS.map((t,i)=>{const p=topicProgress(t);return `<button class="topic-card ${t.color}" data-action="topic" data-id="${t.id}" style="--i:${i}"><div class="card-top"><span class="topic-illustration">${icon(t.icon)}</span><span class="card-index">0${i+1}</span></div><h3>${t.name}</h3><p>${t.description}</p><span class="mechanic">${t.mechanic}</span><div class="card-bottom"><div class="card-progress"><span>${p.n} / ${p.total} vom Blatt gelöst</span><div class="meter"><i style="width:${p.pct}%"></i></div></div><span class="round-arrow">${icon('arrow')}</span></div></button>`;}).join('')}</section>
 <section class="bottom-grid"><div class="daily-card"><div class="eyebrow">KLEINE SCHRITTE ZÄHLEN</div><h3>Dein Garten heute</h3><div class="flower-row">${Array.from({length:8},(_,i)=>`<span class="daily-flower ${i<d.solved?'grown':''}" aria-label="${i<d.solved?'Aufgabe geschafft':'Noch frei'}">✿</span>`).join('')}</div><p><b>${d.solved}</b> Aufgaben bearbeitet · ${d.correct} ohne Hilfe beim ersten Versuch.<br>Eine Runde ist ein Vorschlag, kein Tageslimit.</p></div><div class="exam-card"><span class="exam-icon">${icon('book')}</span><div><div class="eyebrow">EIN KLEINER PROBELAUF</div><h3>Bereit fürs Übungsblatt?</h3><p>Alle 19 Original-Teilaufgaben.<br>Mit Auswertung am Ende, ohne Zeitdruck.</p><button class="text-button" data-action="exam">Proberunde starten ${icon('arrow')}</button></div></div></section>
 <section class="week-plan"><div><div class="eyebrow">DEIN WEG BIS FREITAG</div><h3>Ein Vorschlag. Dein Tempo.</h3></div>${[['Di · 10.11.','Zahlen & Farben','binary'],['Mi · 11.11.','Modulo & Formeln','formula'],['Do · 12.11.','Logiklabor & Proberunde','truth'],['Fr · 13.11.','Kurz wiederholen','review']].map((v,i)=>`<button data-action="${v[2]==='review'?'review':'topic'}" data-id="${v[2]}" class="day-step ${TODAY==='2026-11-'+(10+i)?'today':''}"><small>${v[0]}</small><b>${v[1]}</b></button>`).join('')}</section>`);
}
function topicPage(id){
 const t=TOPICS.find(t=>t.id===id);if(!t)return;view='topic';selectedTopic=id;const p=topicProgress(t),count=QUESTIONS.filter(q=>q.topic===id).length;
 shell(`<button class="back-link" data-action="home">${icon('back')} Zurück in den Garten</button><section class="topic-intro ${t.color}"><div><div class="eyebrow">DEINE THEMENINSEL</div><h1>${t.name}</h1><p>${t.description}</p><span class="tag">${count} Aufgaben · ${t.mechanic}</span></div><span class="big-topic-icon">${icon(t.icon)}</span></section><div class="topic-layout"><section class="learning-card"><div class="eyebrow">ERST EIN KLEINER GEDANKE</div><h2>Das steckt dahinter</h2><p>${t.lesson}</p><div class="example"><b>Zum Beispiel</b><p>${t.example}</p></div><button class="btn primary" data-action="practice" data-id="${id}">Eine Spielrunde starten ${icon('arrow')}</button><p class="muted small-text">6 Aufgaben · Hinweise verfügbar · neue Mischung pro Runde</p></section><section class="learning-card topic-options"><h3>So möchtest du üben</h3><button class="option-card" data-action="original" data-id="${id}">${icon('book')}<span><b>Genau wie auf dem Blatt</b><small>Alle ${p.total} Originalaufgaben dieses Themas</small></span>${icon('arrow')}</button><button class="option-card" data-action="practice" data-id="${id}">${icon('leaf')}<span><b>Eine bunte Mischung</b><small>Originale und zusätzliche Aufgaben</small></span>${icon('arrow')}</button><div class="mastery"><span>${p.n} von ${p.total} Originalaufgaben ohne Hilfe gelöst</span><div class="meter"><i style="width:${p.pct}%"></i></div><small>Das zeigt deinen Übungsstand, keine Klausurnote.</small></div></section></div>`);
}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function chooseRound(topic,count){return shuffle(QUESTIONS.filter(q=>!topic||q.topic===topic)).sort((a,b)=>(store.records[a.id]?.missed?-3:store.records[a.id]?.clean||0)-(store.records[b.id]?.missed?-3:store.records[b.id]?.clean||0)).slice(0,count).map(q=>q.id);}
function start(ids,title,m='practice'){
 if(!ids.length){showModal('Alles darf noch wachsen',`<p>Hier ist noch keine Fehleraufgabe. Starte eine Tagesrunde oder suche dir eine Themeninsel aus.</p><button class="btn primary" data-action="daily">Tagesrunde starten ${icon('arrow')}</button>`);return;}
 session={ids,index:0,results:[],mode:m,title};mode=m;store.session=session;save();loadQuestion();
}
function daily(){const ids=TOPICS.map(t=>chooseRound(t.id,1)[0]);const extras=chooseRound(null,QUESTIONS.length).filter(id=>!ids.includes(id)).slice(0,2);start([...ids,...extras],'Meine kleine Tagesrunde','daily');}
function loadQuestion(){
 view='game';mode=session.mode;const q=QUESTIONS.find(q=>q.id===session.ids[session.index]);
 qState={answer:q.kind==='input'?q.fields.map(()=>''):q.kind==='bits'?0:q.kind==='formula'?'':q.kind==='equiv'?{equal:null,reason:null}:q.kind==='table'?q.rows.map(()=>q.cols.map(()=>null)):q.kind==='match'?{}:null,attempts:0,hinted:false,revealed:false,done:false,feedback:null,left:null,selected:false,order:q.kind==='match'?shuffle(q.pairs.map((_,i)=>i)):null};
 if(session.draft?.id===q.id){const draft=cleanDraft(session.draft);qState.answer=draft.answer;qState.attempts=draft.attempts;qState.hinted=draft.hinted;}delete session.draft;
 shell(`<div class="game-top"><button class="back-link" data-action="leave">${icon('back')} Pause & Garten</button><span>${esc(session.title)}</span><span class="game-counter">${session.index+1} <small>/ ${session.ids.length}</small></span></div><div class="session-meter"><i style="width:${session.index/session.ids.length*100}%"></i></div><div id="game"></div>`);renderGame();$('#question-title')?.focus();window.scrollTo({top:0,behavior:'instant'});
}
function current(){return QUESTIONS.find(q=>q.id===session.ids[session.index]);}
function renderGame(){
 const q=current(),t=TOPICS.find(t=>t.id===q.topic);const focused=document.activeElement?.dataset?.key,tableScroll=$('.truth-scroll')?.scrollLeft||0;
 $('#game').innerHTML=`<section class="game-card"><div class="question-meta"><span class="tag ${t.color}">${icon(t.icon)} ${t.name}</span><span>${q.original?'Aus deinem Blatt · '+q.id.replace('o','Aufgabe '):'Zusatzaufgabe'} ${mode==='exam'?'· Proberunde':''}</span></div><h2 id="question-title" tabindex="-1">${q.title}</h2><p class="question-prompt">${q.prompt}</p><div id="playground" class="playground ${q.kind}">${playground(q)}</div>${qState.hinted?`<div class="hint-box">${icon('sun')}<div><b>Ein kleiner Hinweis</b><p>${q.hint}</p></div></div>`:''}<div id="feedback" aria-live="polite">${feedbackHTML(q)}</div><div class="game-controls">${qState.done?`<span class="muted">${mode==='exam'?'Antwort gespeichert.':'Gut, dass du drangeblieben bist.'}</span><button class="btn primary" data-action="next">${session.index===session.ids.length-1?'Runde abschließen':'Weiter geht’s'} ${icon('arrow')}</button>`:`<div class="help-actions">${mode!=='exam'?`<button class="text-button" data-action="hint">${icon('sun')} Kleiner Hinweis</button>${qState.attempts?'<button class="text-button" data-action="reveal">Lösung ansehen</button>':''}`:'<span class="muted">Auswertung am Ende</span>'}</div><button class="btn primary" data-action="check">Antwort prüfen ${icon('check')}</button>`}</div></section><p class="game-footnote">${mode==='exam'?'Du kannst ohne Zeitlimit arbeiten. Hilfen und Lösungen kommen in der Auswertung.':'Fehler sind kleine Wegweiser. Du darfst es noch einmal versuchen.'}</p>`;
 $$('#playground [data-action]').forEach(el=>{if(!el.dataset.key)el.dataset.key=el.dataset.action+':'+(el.dataset.value||'');if(['equal','reason'].includes(el.dataset.action))el.setAttribute('aria-pressed',String(el.classList.contains('chosen')));});
 if($('.truth-scroll'))$('.truth-scroll').scrollLeft=tableScroll;
 if(focused){const el=$$('[data-key]').find(el=>el.dataset.key===focused);el?.focus({preventScroll:true});}
 $$('[data-drag]').forEach(el=>{el.draggable=false;});
 if(qState.done)$('[data-action="next"]')?.focus({preventScroll:true});
 if(q.kind==='match')requestAnimationFrame(drawConnections);
}
function playground(q){const a=qState.answer,disabled=qState.done?'disabled':'';
 if(q.kind==='input')return `${q.topic==='hex'?'<div class="color-dots"><i></i><i></i><i></i></div>':''}<div class="input-fields">${q.fields.map((f,i)=>`<label class="answer-label">${f.label}<input data-field="${i}" data-key="field${i}" value="${esc(a[i])}" inputmode="${f.format==='number'?'numeric':'text'}" autocomplete="off" spellcheck="false" placeholder="${f.format==='hex'?'#______':'Deine Zahl'}" ${disabled}></label>`).join('')}</div>`;
 if(q.kind==='bits'){const vals=Array.from({length:q.width},(_,i)=>2**(q.width-i-1));return `<div class="target-number"><small>DEINE ZIELZAHL</small><strong>${q.target}<sub>10</sub></strong></div><div class="bit-row">${vals.map((v,i)=>`<button class="bit ${(a&v)?'on':''}" data-action="bit" data-value="${v}" data-key="bit${i}" aria-label="Stellenwert ${v}" aria-pressed="${!!(a&v)}" ${disabled}><span class="bulb"></span><b>${a&v?1:0}</b><small>${v}</small></button>`).join('')}</div><div class="binary-reading"><span>Deine Zahl: <b>${a.toString(2).padStart(q.width,'0')}₂</b></span>${mode==='exam'?'':`<span>Summe: <b>${a}</b></span>`}</div>`;}
 if(q.kind==='choice')return `<div class="choices">${q.options.map((s,i)=>`<button class="choice ${a===i?'chosen':''}" data-action="choose" data-value="${i}" data-key="choice${i}" aria-pressed="${a===i}" ${disabled}><span class="choice-letter">${'ABCD'[i]}</span>${esc(s)}</button>`).join('')}</div>`;
 if(q.kind==='cycle')return `<div class="counter-cloud">${icon('repeat')}<span>Zähler <b>${q.n}</b></span><small>Platz = Zähler mod ${q.names.length}</small></div><div class="cycle-track">${q.names.map((n,i)=>`<button class="cycle-creature ${a===i?'chosen':''}" data-action="choose" data-value="${i}" data-key="cycle${i}" aria-pressed="${a===i}" ${disabled}><span class="creature-face face${i}"><i></i><i></i><b>⌣</b></span><small>PLATZ ${i}</small><b>${n}</b><span class="cycle-arrow">↻</span></button>`).join('')}</div><p class="interaction-help">Wähle den richtigen Platz. Nach dem letzten beginnt der Zyklus wieder bei 0.</p>`;
 if(q.kind==='sort')return `<button class="letter-card ${qState.selected?'selected':''}" data-drag="letter" data-action="select-letter" data-key="letter" ${disabled}>${icon('mail')}<span>${esc(q.text)}</span><small>Ziehen oder antippen</small></button><div class="sort-bins">${q.options.map((s,i)=>`<button class="sort-bin ${a===i?'chosen':''}" data-action="sort" data-drop="sort" data-value="${i}" data-key="bin${i}" aria-pressed="${a===i}" ${disabled}><span>${['☀','☁','!','∑'][i]}</span><b>${s}</b>${a===i?'<small>Karte liegt hier ✓</small>':'<small>Hier ablegen</small>'}</button>`).join('')}</div>`;
 if(q.kind==='match')return `<div class="paint-swatch" style="--paint:${q.swatch}"><span>${q.swatch}</span></div><p class="interaction-help">Links auswählen, dann rechts verbinden. Du kannst die linke Karte auch ziehen.</p><div class="match-board"><svg id="connection-lines" aria-hidden="true"></svg><div class="match-col">${q.pairs.map((p,i)=>`<button data-action="match-left" data-drag="match" data-value="${i}" data-key="left${i}" class="match-node left-node ${qState.left===i?'selected':''} ${a[i]!==undefined?'connected':''}" ${disabled}>${p[0]}<span class="port"></span></button>`).join('')}</div><div class="match-col">${qState.order.map(i=>`<button data-action="match-right" data-drop="match" data-value="${i}" data-key="right${i}" class="match-node right-node ${Object.values(a).includes(i)?'connected':''}" ${disabled}><span class="port"></span>${q.pairs[i][1]}</button>`).join('')}</div></div><button class="text-button" data-action="clear-matches" ${disabled}>Verbindungen neu legen</button>`;
 if(q.kind==='formula')return `<div class="legend">${q.legend.map(s=>`<span>${s}</span>`).join('')}</div><div class="formula-zone" data-drop="formula" aria-label="Deine gebaute Formel"><span>${a?esc(a):'Hier wächst deine Formel …'}</span><button class="icon-button" data-action="undo" aria-label="Letzten Baustein entfernen" ${disabled}>⌫</button></div><div class="token-tray">${['A','B','C','¬','∧','∨','⊕','(',')'].map((s,i)=>`<button class="token ${i<3?'letter-token':''}" data-drag="token" data-action="token" data-token="${s}" data-key="token${i}" aria-label="${{'¬':'NICHT','∧':'UND','∨':'ODER','⊕':'ENTWEDER ODER','(':'Klammer auf',')':'Klammer zu'}[s]||s}" ${disabled}>${s}</button>`).join('')}</div><p class="interaction-help">Bausteine antippen oder in die Formel ziehen. ¬ nicht · ∧ und · ∨ oder · ⊕ entweder oder</p>`;
 if(q.kind==='equiv')return `<div class="formula-comparison"><div>${q.left}</div><span>?</span><div>${q.right}</div></div><div class="equiv-buttons"><button class="choice ${a.equal===true?'chosen':''}" data-action="equal" data-value="true" ${disabled}>≡ Gleichbedeutend</button><button class="choice ${a.equal===false?'chosen':''}" data-action="equal" data-value="false" ${disabled}>≢ Unterschiedlich</button></div><h3 class="reason-heading">Und warum?</h3><div class="choices compact">${q.reasons.map((s,i)=>`<button class="choice ${a.reason===i?'chosen':''}" data-action="reason" data-value="${i}" ${disabled}>${s}</button>`).join('')}</div>`;
 if(q.kind==='table')return `<div class="table-formula">${q.formula}</div><p class="interaction-help">? → w → f · „w“ = wahr, „f“ = falsch. Alle ${q.rows.length*q.cols.length} Felder gehören dazu.<br>Auf kleinen Bildschirmen kannst du die Tabelle seitlich schieben.</p><div class="truth-scroll" role="region" aria-label="Wahrheitstafel, horizontal scrollbar" tabindex="0"><table class="truth-table"><thead><tr><th>A</th><th>B</th><th>C</th>${q.cols.map((c,j)=>`<th class="${j===q.cols.length-1?'result-col':''}">${c}</th>`).join('')}</tr></thead><tbody>${q.rows.map((r,i)=>`<tr><td>${r.A?'w':'f'}</td><td>${r.B?'w':'f'}</td><td>${r.C?'w':'f'}</td>${q.cols.map((c,j)=>`<td class="${j===q.cols.length-1?'result-col':''}"><button class="truth-cell ${a[i][j]===null?'empty':a[i][j]?'true':'false'} ${qState.feedback?.bad?.some(([x,y])=>x===i&&y===j)?'incorrect-cell':''}" data-action="cell" data-row="${i}" data-col="${j}" data-key="cell${i}-${j}" aria-label="Zeile ${i+1}: A ${r.A?'wahr':'falsch'}, B ${r.B?'wahr':'falsch'}, C ${r.C?'wahr':'falsch'}; ${c}: ${a[i][j]===null?'noch offen':a[i][j]?'wahr':'falsch'}" ${disabled}>${a[i][j]===null?'?':a[i][j]?'w':'f'}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="table-count">${a.flat().filter(v=>v!==null).length} / ${q.rows.length*q.cols.length} Felder ausgefüllt</p>`;
 return '';
}
function drawConnections(){const board=$('.match-board'),svg=$('#connection-lines');if(!board||!svg)return;const rect=board.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${rect.width} ${rect.height}`);svg.innerHTML=Object.entries(qState.answer).map(([l,r])=>{const le=$(`[data-key="left${l}"] .port`)?.getBoundingClientRect(),re=$(`[data-key="right${r}"] .port`)?.getBoundingClientRect();if(!le||!re)return '';const x1=le.x+le.width/2-rect.x,y1=le.y+le.height/2-rect.y,x2=re.x+re.width/2-rect.x,y2=re.y+re.height/2-rect.y;return `<path d="M${x1} ${y1} C${x1+45} ${y1},${x2-45} ${y2},${x2} ${y2}" stroke="${['#aa83b0','#6b9b87','#cc9d58'][l]}"/>`;}).join('');}
function feedbackHTML(q){const f=qState.feedback;if(!f)return '';return `<div class="feedback ${f.type}"><span>${f.type==='success'?'✿':f.type==='error'?'↻':'✧'}</span><div><b>${f.title}</b><p>${f.text}</p>${qState.done&&mode!=='exam'?`<p class="explanation">${q.explanation}</p>`:''}</div></div>`;}
function completeAnswer(q){const a=qState.answer;if(q.kind==='input')return a.every(x=>String(x).trim());if(q.kind==='table')return a.flat().every(x=>x!==null);if(q.kind==='match')return Object.keys(a).length===q.pairs.length;if(q.kind==='equiv')return a.equal!==null&&a.reason!==null;if(q.kind==='formula')return a.length>0;return a!==null;}
function check(){
 if(qState.done)return;const q=current();
 if(!completeAnswer(q)){qState.feedback={type:'info',title:'Hier fehlt noch ein kleines Stück.',text:q.kind==='table'?'Fülle alle Fragezeichen aus. Ein Klick setzt w, ein weiterer f.':'Wähle eine Antwort und fülle alle Teile aus.'};renderGame();return;}
 if(q.kind==='formula'){try{evaluateFormula(qState.answer,{A:false,B:false,C:false});}catch{qState.feedback={type:'info',title:'Die Formel ist noch nicht vollständig.',text:'Zwischen zwei Buchstaben gehört ein Verknüpfungszeichen. Prüfe auch die Klammern.'};renderGame();return;}}
 const correct=checkAnswer(q,qState.answer);qState.attempts++;
 if(mode==='exam'){qState.done=true;qState.feedback={type:'info',title:'Deine Antwort ist gespeichert.',text:'Die Auflösung wartet am Ende der Proberunde.'};session.results.push({id:q.id,correct,assisted:false});renderGame();return;}
 if(correct){const clean=qState.attempts===1&&!qState.hinted&&!qState.revealed;qState.done=true;record(q,clean);session.results.push({id:q.id,correct:clean,assisted:!clean});qState.feedback={type:'success',title:['Das ist aufgeblüht!','Genau richtig!','Ein Stück weitergewachsen!'][session.index%3],text:clean?'+10 Blüten für deinen Garten.':'+5 Blüten fürs Dranbleiben. Diese Aufgabe kommt später noch einmal.'};audio.success();confetti();}
 else{const r=store.records[q.id]||{tries:0,clean:0,missed:false,last:'',streak:0};r.missed=true;r.streak=0;r.last=dayKey();store.records[q.id]=r;updatePoints();qState.feedback={type:'error',title:'Fast. Lass uns noch einmal hinschauen.',text:q.kind==='table'?'Die markierten Felder stimmen noch nicht. Deine richtigen Felder bleiben stehen.':q.kind==='equiv'?'Prüfe sowohl deine Entscheidung als auch die Begründung.':'Ein weiterer Versuch ist okay. Der kleine Hinweis hilft dir beim nächsten Schritt.'};if(q.kind==='table')qState.feedback.bad=q.rows.flatMap((r,i)=>q.cols.flatMap((c,j)=>qState.answer[i][j]!==evaluateFormula(c,r)?[[i,j]]:[]));audio.soft();}
 renderGame();$('#feedback')?.scrollIntoView({behavior:reduced()?'instant':'smooth',block:'nearest'});
}
function record(q,clean,commit=true){refreshDay();const r=store.records[q.id]||{tries:0,clean:0,missed:false,last:'',streak:0};r.tries++;r.clean+=clean?1:0;r.missed=!clean;r.streak=clean?r.streak+1:0;r.last=TODAY;store.records[q.id]=r;store.points+=clean?10:5;const d=store.days[TODAY]||{solved:0,correct:0};d.solved++;d.correct+=clean?1:0;store.days[TODAY]=d;if(commit)save();updatePoints();}
function updatePoints(){const el=$('.points b');if(el)el.textContent=store.points;const count=$('.nav-count');if(count)count.textContent=Object.values(store.records).filter(r=>r.missed).length;}
function reveal(){const q=current();qState.revealed=true;qState.done=true;record(q,false);session.results.push({id:q.id,correct:false,assisted:true});qState.feedback={type:'info',title:'Erst verstehen, dann noch einmal probieren.',text:'Diese Aufgabe landet in „Nochmal wachsen“. +5 Blüten fürs Bearbeiten.'};qState.answer=solution(q);renderGame();}
function solution(q){switch(q.kind){case'input':return q.fields.map(f=>f.answer);case'bits':return q.target;case'choice':case'sort':case'cycle':return q.correct;case'match':return Object.fromEntries(q.pairs.map((_,i)=>[i,i]));case'formula':return q.answer;case'equiv':return {equal:q.equal,reason:q.reason};case'table':return q.rows.map(r=>q.cols.map(c=>evaluateFormula(c,r)));}}
function next(){if(!qState.done)return;if(session.index===session.ids.length-1){finish();return;}session.index++;store.session=session;save();loadQuestion();}
function leave(){if(qState?.done&&session.index===session.ids.length-1){finish();return;}persistRound();home();}
function finish(){
 if(mode==='exam')session.results.forEach(r=>record(QUESTIONS.find(q=>q.id===r.id),r.correct,false));
 store.session=null;save();view='result';const correct=session.results.filter(r=>r.correct).length,wrong=session.results.filter(r=>!r.correct).map(r=>r.id);const title=mode==='exam'?'Dein Probelauf ist geschafft.':'Dein Garten ist gewachsen.';
 shell(`<section class="result-hero">${mascot('result')}<div class="eyebrow">${esc(session.title)}</div><h1>${title}</h1><p><b>${correct} von ${session.ids.length}</b> Aufgaben hast du ${mode==='exam'?'richtig':'beim ersten Versuch ohne Hilfe'} gelöst.<br>${wrong.length?'Die kniffligen Stellen dürfen noch ein bisschen wachsen.':'Nimm das gute Gefühl mit. Du hast dir Zeit zum Verstehen genommen.'}</p><div class="result-actions">${wrong.length?`<button class="btn primary" data-action="retry-round">${icon('repeat')} Diese ${wrong.length} nochmal üben</button>`:'<button class="btn primary" data-action="daily">Noch eine kleine Runde</button>'}<button class="btn" data-action="home">Zurück in den Garten</button></div></section><section class="review-results"><h2>Deine kleinen Erkenntnisse</h2>${session.results.map(r=>{const q=QUESTIONS.find(q=>q.id===r.id);return `<details class="result-detail"><summary><span class="result-status ${r.correct?'good':''}">${r.correct?'✓':'↻'}</span><span><b>${q.title}</b><small>${TOPICS.find(t=>t.id===q.topic).label} · ${q.original?'Original '+q.id.slice(1):'Zusatzaufgabe'} · ${r.correct?'ohne Hilfe geschafft':'noch einmal üben'}</small></span><span>+</span></summary><div><p>${q.prompt}</p>${solutionHTML(q)}<p>${q.explanation}</p></div></details>`;}).join('')}</section>`);confetti();window.scrollTo(0,0);
}
function solutionHTML(q){if(q.kind==='table')return `<div class="truth-scroll"><table class="solution-table"><thead><tr><th>A</th><th>B</th><th>C</th>${q.cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${q.rows.map(r=>`<tr><td>${r.A?'w':'f'}</td><td>${r.B?'w':'f'}</td><td>${r.C?'w':'f'}</td>${q.cols.map(c=>`<td>${evaluateFormula(c,r)?'w':'f'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;if(q.kind==='formula')return `<div class="example">${q.answer}</div>`;return '';}
function showModal(title,html){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Schließen">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!m.open)m.showModal();window.GardenCloud?.paint();}
function guide(){showModal('Dein kleines Lernbuch',`<p class="muted">Sechs Gedanken zum Mitnehmen. Du kannst jederzeit zurückkommen.</p>${TOPICS.map(t=>`<details class="guide-detail"><summary>${icon(t.icon)} ${t.label}<span>+</span></summary><p>${t.lesson}</p><div class="example">${t.example}</div></details>`).join('')}<div class="example"><b>Die Zeichen in deinem Blatt</b><p>¬ = nicht · ∧ = und · ∨ = oder (auch beides) · ⊕ = entweder oder (genau eines). Das gepunktete Oder im PDF ist dasselbe wie unser ⊕.</p></div>`);}
function sources(){showModal('Direkt aus deinem Übungsblatt',`<p>Grundlage ist <b>Wiederholung für Test 1</b>: zwei Aufgabenseiten und zwei Seiten mit Musterlösungen. Alle <b>19 Teilaufgaben</b> sind enthalten, ergänzt um ${QUESTIONS.length-19} weitere Übungen.</p><p>Formeln, Handschrift und Wahrheitstafeln wurden einzeln geprüft. Jede Spielkarte zeigt, ob sie aus dem Blatt stammt oder eine Zusatzaufgabe ist.</p><p><b>Ein wichtiges Detail:</b> Das gepunktete Oder im Blatt bedeutet XOR, also „entweder oder“. Wir schreiben dafür ⊕. Bei Aufgabe 7b steht in der Lösungstabelle versehentlich „c)“; die Werte gehören zu 7b.</p><p>Die Musterlösung nennt #D11BB0 „Magenta“. Gemeint ist ein Magenta-/Violett-Pink-Ton mit viel Rot und Blau und wenig Grün.</p><p><a class="btn" href="WiederholungFuerTest1.pdf" target="_blank" rel="noopener">Original-PDF öffnen ${icon('book')}</a></p><p>Der Lerntermin ist Freitag, 13. November 2026. Tagesrunden sind Vorschläge und können beliebig oft gespielt werden. Dein Stand wird im Browser gespeichert. Mit Anmeldung wird er zusätzlich privat zwischen deinen Geräten abgeglichen.</p><p class="muted">Illustrationen, Musik und Sounds wurden für diesen Mathegarten erstellt. Die lokale Version funktioniert auch ohne Konto. Für den Geräteabgleich brauchst du eine Internetverbindung und eine Anmeldung.</p>`);}
function settings(){showModal('Mach es dir gemütlich',`<div class="setting-row"><div><b>Leise Gartenmusik</b><small>Sanfte Akkorde und kleine Glockentöne</small></div><button class="btn small" data-action="music">${audioOn?'Musik ausschalten':'Musik einschalten'}</button></div><label class="setting-row"><div><b>Lautstärke</b><small>Gilt für Musik und Spieltöne</small></div><input id="volume" type="range" min="0" max="100" value="${store.settings.volume}" aria-label="Lautstärke"></label><label class="setting-row"><div><b>Spieltöne</b><small>Ein kleiner Klang beim Lösen</small></div><input id="sfx" type="checkbox" ${store.settings.sfx?'checked':''}></label><label class="setting-row"><div><b>Weniger Bewegung</b><small>Ruhige Oberfläche, ohne Konfetti</small></div><input id="reduce" type="checkbox" ${store.settings.reduce?'checked':''}></label><h3>Deinen Garten mitnehmen</h3><p>Verbinde PC und Handy mit demselben Konto. Dein Lernstand und angefangene Runden werden dann automatisch abgeglichen. Eine zusätzliche Sicherung kannst du hier als Datei mitnehmen.</p><button class="btn primary cloud-settings" data-cloud-action="open">PC & Handy verbinden <span data-cloud-status></span></button><div class="setting-buttons"><button class="btn" data-action="export">Fortschritt sichern</button><label class="btn file-label">Sicherung einlesen<input id="import-file" type="file" accept=".json,application/json" hidden></label></div><details class="backup-text"><summary>Sicherung als Text kopieren oder einfügen</summary><textarea id="backup" aria-label="Sicherungstext" placeholder="Hier erscheint dein Sicherungstext, oder du fügst eine frühere Sicherung ein."></textarea><button class="btn small" data-action="export-text">Text erzeugen</button><button class="btn small" data-action="import-text">Text einlesen</button></details><div class="example"><b>Auf dem Smartphone</b><p>Öffne <a href="https://mertde1999.github.io/andre-tuerkisch/mathegarten/">deinen Mathegarten</a> im Handy-Browser. Mit demselben Konto kannst du dort weiterlernen. Die lokale HTML-Datei bleibt zusätzlich als Offline-Version nutzbar.</p></div><p class="muted">Speicherstatus: ${storageOK?'Lokale Speicherung aktiv.':'Speicherung eingeschränkt – bitte regelmäßig sichern.'}</p>`);}
function backup(){return JSON.stringify({...store,session:null},null,2);}
function exportData(){const blob=new Blob([backup()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Mathegarten-Fortschritt-${TODAY}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if($('#backup'))$('#backup').value=backup();toast('Sicherung vorbereitet. Du kannst sie auch als Text kopieren.');}
function importData(text){try{const data=validateStore(JSON.parse(text));for(const [id,r] of Object.entries(data.records)){const old=store.records[id];if(!old||r.last>old.last||r.last===old.last&&r.tries>old.tries)store.records[id]=r;}for(const [d,v] of Object.entries(data.days)){const old=store.days[d]||{solved:0,correct:0};store.days[d]={solved:Math.max(old.solved,v.solved),correct:Math.max(old.correct,v.correct)};}store.points=Math.max(store.points,data.points);save();$('#modal').close();home();toast('Dein gesicherter Fortschritt ist wieder im Garten.');}catch{toast('Diese Sicherung konnte ich nicht lesen. Bitte eine Mathegarten-JSON oder den vollständigen Sicherungstext verwenden.');}}
function reduced(){return store.settings.reduce||window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
function confetti(){if(reduced())return;const canvas=$('#confetti'),ctx=canvas.getContext('2d');canvas.width=innerWidth;canvas.height=innerHeight;const colors=['#b6d1a6','#eeb7b5','#c6b6df','#f0ce7e','#a9cbd5'];const parts=Array.from({length:58},()=>({x:innerWidth/2,y:innerHeight*.43,vx:(Math.random()-.5)*14,vy:-4-Math.random()*10,rot:Math.random()*6,size:5+Math.random()*5,color:colors[Math.floor(Math.random()*colors.length)]}));let f=0;cancelAnimationFrame(confetti.frame);function frame(){ctx.clearRect(0,0,canvas.width,canvas.height);for(const p of parts){p.x+=p.vx;p.y+=p.vy;p.vy+=.17;p.rot+=.06;ctx.save();ctx.globalAlpha=Math.min(1,(140-f)/35);ctx.fillStyle=p.color;ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*.6);ctx.restore();}if(f++<140)confetti.frame=requestAnimationFrame(frame);else ctx.clearRect(0,0,canvas.width,canvas.height);}frame();}

const audio={ctx:null,master:null,music:null,interval:null,step:0,
 init(){if(!this.ctx){const A=window.AudioContext||window.webkitAudioContext;if(!A)return false;this.ctx=new A();this.master=this.ctx.createGain();this.master.connect(this.ctx.destination);this.music=this.ctx.createGain();this.music.connect(this.master);}this.master.gain.setTargetAtTime(store.settings.volume/100*.5,this.ctx.currentTime,.1);if(this.ctx.state==='suspended')this.ctx.resume();return true;},
 tone(freq,start,duration,level=.1,type='sine',dest){const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(level,start+.03);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g);g.connect(dest||this.master);o.start(start);o.stop(start+duration+.03);o.onended=()=>{o.disconnect();g.disconnect();};},
 chord(){if(!audioOn||document.hidden||!this.ctx)return;const chords=[[130.81,164.81,196,246.94],[110,130.81,164.81,196],[87.31,130.81,174.61,220],[98,146.83,196,246.94]],ch=chords[this.step++%chords.length],t=this.ctx.currentTime+.05;ch.forEach((n,i)=>this.tone(n,t+i*.025,3.5,.065,'sine',this.music));[0,2,1,3,2,1,3,2].forEach((j,i)=>this.tone(ch[j]*2,t+i*.44,1.5,.08,'triangle',this.music));},
 toggle(){if(!this.init()){toast('Dieser Browser kann die Gartenmusik leider nicht abspielen.');return;}audioOn=!audioOn;clearInterval(this.interval);if(audioOn){this.music.gain.setTargetAtTime(1,this.ctx.currentTime,.25);this.chord();this.interval=setInterval(()=>this.chord(),3520);}else this.music.gain.setTargetAtTime(0,this.ctx.currentTime,.15);const b=$('#music-toggle');if(b){b.classList.toggle('playing',audioOn);b.setAttribute('aria-pressed',String(audioOn));b.querySelector('span').textContent=`Musik ${audioOn?'an':'aus'}`;}if($('#modal')?.open)settings();},
 success(){if(!store.settings.sfx||!this.init())return;[523.25,659.25,783.99].forEach((n,i)=>this.tone(n,this.ctx.currentTime+i*.11,.8,.13));},
 soft(){if(!store.settings.sfx||!this.init())return;this.tone(293.66,this.ctx.currentTime,.25,.06);}
};
document.addEventListener('visibilitychange',()=>{if(audio.ctx){if(document.hidden)audio.ctx.suspend();else if(audioOn)audio.ctx.resume();}if(!document.hidden&&TODAY!==dayKey()){refreshDay();if(view==='home')home();}});
window.addEventListener('resize',()=>{if(view==='game'&&current().kind==='match')drawConnections();});

let suppressClickUntil=0,drag=null;
function applyDrop(d,target){if(!target||!qState||qState.done||view!=='game')return;const q=current(),v=Number(target.dataset.value);if(d.type==='letter'&&q.kind==='sort'&&target.dataset.drop==='sort'&&Number.isInteger(v)&&v>=0&&v<q.options.length)qState.answer=v;if(d.type==='match'&&q.kind==='match'&&target.dataset.drop==='match'&&Number.isInteger(+d.value)&&+d.value>=0&&+d.value<q.pairs.length&&Number.isInteger(v)&&v>=0&&v<q.pairs.length){qState.left=+d.value;connect(v);}if(d.type==='token'&&q.kind==='formula'&&target.dataset.drop==='formula'&&['A','B','C','¬','∧','∨','⊕','(',')'].includes(d.token)&&qState.answer.length<100)qState.answer+=d.token;renderGame();persistRound();}
app.addEventListener('dragstart',e=>{if(e.target.closest('[data-drag]'))e.preventDefault();});
app.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-drag]');if(!el||el.disabled||e.button!==0)return;e.preventDefault();el.setPointerCapture(e.pointerId);drag={el,type:el.dataset.drag,value:el.dataset.value,token:el.dataset.token,x:e.clientX,y:e.clientY,moved:false,id:e.pointerId};});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>9){drag.moved=true;drag.ghost=drag.el.cloneNode(true);drag.ghost.classList.add('drag-ghost');drag.ghost.style.width=drag.el.offsetWidth+'px';drag.ghost.removeAttribute('id');document.body.append(drag.ghost);}if(drag.moved){e.preventDefault();drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';$$('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.classList.add('drop-hover');}},{passive:false});
document.addEventListener('pointerup',e=>{if(!drag)return;const d=drag;drag=null;if(d.moved){suppressClickUntil=Date.now()+350;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');d.ghost?.remove();$$('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));applyDrop(d,target);}});
document.addEventListener('pointercancel',()=>{drag?.ghost?.remove();drag=null;$$('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));});
function connect(right){if(qState.left===null){toast('Wähle zuerst einen Farbanteil auf der linken Seite.');return;}for(const [k,v] of Object.entries(qState.answer))if(v===right)delete qState.answer[k];qState.answer[qState.left]=right;qState.left=null;}
app.addEventListener('input',e=>{if(e.target.dataset.field!==undefined&&qState&&!qState.done){qState.answer[+e.target.dataset.field]=e.target.value;persistRound();}if(e.target.id==='volume'){store.settings.volume=+e.target.value;save();if(audio.ctx)audio.master.gain.setTargetAtTime(store.settings.volume/100*.5,audio.ctx.currentTime,.1);}});
app.addEventListener('change',async e=>{if(e.target.id==='sfx'){store.settings.sfx=e.target.checked;save();}if(e.target.id==='reduce'){store.settings.reduce=e.target.checked;document.body.classList.toggle('reduced',store.settings.reduce);save();}if(e.target.id==='import-file'&&e.target.files[0]){if(e.target.files[0].size>2e6){toast('Die Sicherung ist unerwartet groß. Bitte eine Mathegarten-Sicherung wählen.');return;}importData(await e.target.files[0].text());}});
app.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input[data-field]')){e.preventDefault();check();persistRound();}});
app.addEventListener('click',e=>{
 if(Date.now()<suppressClickUntil){e.preventDefault();return;}
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,v=b.dataset.value;
 if(['home','topic','daily','review','exam','practice','original'].includes(a)&&$('#modal')?.open)$('#modal').close();
 switch(a){
 case'home':if(view==='game')leave();else home();break;
 case'topic':if(view==='game')persistRound();topicPage(id);break;
 case'daily':daily();break;
 case'review':start(QUESTIONS.filter(q=>store.records[q.id]?.missed).map(q=>q.id),'Nochmal wachsen','review');break;
 case'exam':start(QUESTIONS.filter(q=>q.original).map(q=>q.id),'Dein Original-Probelauf','exam');break;
 case'practice':start(chooseRound(id,6),TOPICS.find(t=>t.id===id).name);break;
 case'original':start(QUESTIONS.filter(q=>q.original&&q.topic===id).map(q=>q.id),'Originale · '+TOPICS.find(t=>t.id===id).label,'original');break;
 case'resume':session=store.session;mode=session.mode;if(session.index===session.ids.length)finish();else loadQuestion();break;
 case'leave':leave();break;
 case'next':next();break;
 case'check':check();break;
 case'hint':if(qState.done)break;qState.hinted=true;renderGame();break;
 case'reveal':reveal();break;
 case'choose':case'sort':qState.answer=+v;renderGame();break;
 case'bit':qState.answer^=+v;renderGame();break;
 case'select-letter':qState.selected=!qState.selected;renderGame();break;
 case'token':if(qState.answer.length<100)qState.answer+=b.dataset.token;renderGame();break;
 case'undo':qState.answer=qState.answer.slice(0,-1);renderGame();break;
 case'match-left':qState.left=+v;renderGame();break;
 case'match-right':connect(+v);renderGame();break;
 case'clear-matches':qState.answer={};qState.left=null;renderGame();break;
 case'equal':qState.answer.equal=v==='true';renderGame();break;
 case'reason':qState.answer.reason=+v;renderGame();break;
 case'cell':{const r=+b.dataset.row,c=+b.dataset.col;qState.answer[r][c]=qState.answer[r][c]===null?true:!qState.answer[r][c];qState.feedback=null;renderGame();break;}
 case'retry-round':{const ids=session.results.filter(r=>!r.correct).map(r=>r.id);start(ids,'Die kleinen Knacknüsse','review');break;}
 case'guide':guide();break;
 case'sources':sources();break;
 case'settings':settings();break;
 case'close-modal':$('#modal').close();break;
 case'music':audio.toggle();break;
 case'export':exportData();break;
 case'export-text':$('#backup').value=backup();$('#backup').select();break;
 case'import-text':importData($('#backup').value);break;
 }
 if(view==='game')persistRound();
});
window.addEventListener('beforeunload',()=>persistRound());
home();
window.GardenCloud?.init({
 get:()=>store,validate:validateStore,escape:esc,modal:showModal,toast,home,
 put:data=>{const next=validateStore({...data,settings:store.settings});if(JSON.stringify(next)===JSON.stringify(store))return;store=next;cloudApplying=true;save();cloudApplying=false;if(view==='home'&&!$('#modal')?.open)home();},
 refreshLocal:()=>{try{const raw=localStorage.getItem(STORAGE);if(raw){const next=validateStore(JSON.parse(raw));if(JSON.stringify(next)!==JSON.stringify(store)){store=next;if(view==='home'&&!$('#modal')?.open)home();}}}catch{}}
});
